import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    full = (1 << n) - 1
    pal = [0] * (1 << n)
    for m in range(1, 1 << n):
        t = [s[i] for i in range(n) if m >> i & 1]
        if t == t[::-1]:
            pal[m] = len(t)
    best = 0
    for m in range(1, 1 << n):
        if not pal[m]:
            continue
        rest = full ^ m
        sub = rest
        while sub:
            if pal[sub]:
                v = pal[m] * pal[sub]
                if v > best:
                    best = v
            sub = (sub - 1) & rest
    print(best)

